        #region [4. 대상 프로세스 포커스 감시 및 오버레이 제어 (Target Focus & Overlay Visibility)]
        /// <summary>
        /// 현재 포그라운드 창이 대상 프로세스(InphaseNXD.exe)에 속하는지 확인합니다.
        /// </summary>
        private bool IsTargetProcessFocused()
        {
            try
            {
                IntPtr fgWindow = GetForegroundWindow();
                if (fgWindow == IntPtr.Zero) return false;

                GetWindowThreadProcessId(fgWindow, out uint fgPid);
                if (fgPid == 0) return false;

                using (Process proc = Process.GetProcessById((int)fgPid))
                {
                    return string.Equals(proc.ProcessName, TARGET_PROCESS_NAME, StringComparison.OrdinalIgnoreCase);
                }
            }
            catch
            {
                return false;
            }
        }

        /// <summary>
        /// 대상 프로세스(InphaseNXD.exe)의 활성 창 핸들을 조회합니다.
        /// </summary>
        private IntPtr GetTargetProcessWindowHandle()
        {
            try
            {
                IntPtr fgWindow = GetForegroundWindow();
                if (fgWindow != IntPtr.Zero)
                {
                    GetWindowThreadProcessId(fgWindow, out uint fgPid);
                    if (fgPid != 0)
                    {
                        using (Process fgProc = Process.GetProcessById((int)fgPid))
                        {
                            if (string.Equals(fgProc.ProcessName, TARGET_PROCESS_NAME, StringComparison.OrdinalIgnoreCase) && IsWindowVisible(fgWindow))
                            {
                                return fgWindow;
                            }
                        }
                    }
                }

                Process[] procs = Process.GetProcessesByName(TARGET_PROCESS_NAME);
                try
                {
                    for (int i = 0; i < procs.Length; i++)
                    {
                        Process p = procs[i];
                        if (p.MainWindowHandle != IntPtr.Zero && IsWindowVisible(p.MainWindowHandle))
                        {
                            return p.MainWindowHandle;
                        }

                        IntPtr found = IntPtr.Zero;
                        foreach (ProcessThread t in p.Threads)
                        {
                            EnumThreadWindows((uint)t.Id, (hWnd, lParam) =>
                            {
                                if (IsWindowVisible(hWnd))
                                {
                                    found = hWnd;
                                    return false;
                                }
                                return true;
                            }, IntPtr.Zero);

                            if (found != IntPtr.Zero)
                            {
                                return found;
                            }
                        }
                    }
                }
                finally
                {
                    for (int i = 0; i < procs.Length; i++)
                    {
                        procs[i].Dispose();
                    }
                }
            }
            catch
            {
            }

            return IntPtr.Zero;
        }

        /// <summary>
        /// 현재 "TalesWeaver 실행 중에만 활성화" 옵션과 포커스 상태를 기준으로 기능 동작이 허용되는지 반환합니다.
        /// </summary>
        private bool IsFeatureActiveNow()
        {
            if (!this._onlyWhenTalesWeaverRunning)
            {
                return true;
            }

            return this.IsTargetProcessFocused();
        }

        /// <summary>
        /// "TalesWeaver 실행 중에만 활성화" 버튼의 텍스트와 시각적 활성 상태를 동기화합니다.
        /// </summary>
        private void SyncOnlyWhenTalesWeaverRunningUi()
        {
            if (this.button_OnlyWhenTalesWeaverRunning == null) return;

            this.button_OnlyWhenTalesWeaverRunning.UseVisualStyleBackColor = false;
            if (this._onlyWhenTalesWeaverRunning)
            {
                this.button_OnlyWhenTalesWeaverRunning.Text = "TalesWeaver 실행 중에만 활성화: ON";
                this.button_OnlyWhenTalesWeaverRunning.BackColor = Color.FromArgb(212, 237, 218);
                this.button_OnlyWhenTalesWeaverRunning.ForeColor = Color.FromArgb(21, 87, 36);
            }
            else
            {
                this.button_OnlyWhenTalesWeaverRunning.Text = "TalesWeaver 실행 중에만 활성화: OFF";
                this.button_OnlyWhenTalesWeaverRunning.BackColor = Color.FromArgb(240, 240, 240);
                this.button_OnlyWhenTalesWeaverRunning.ForeColor = SystemColors.ControlText;
            }
        }

        /// <summary>
        /// 대상 프로세스의 포커스 상태를 주기적으로 감시하는 타이머를 시작합니다.
        /// </summary>
        private void StartFocusMonitor()
        {
            if (this._focusCheckTimer != null) return;

            this._focusCheckTimer = new Timer
            {
                Interval = FOCUS_POLL_INTERVAL_MS
            };
            this._focusCheckTimer.Tick += FocusCheckTimer_Tick;
            this._focusCheckTimer.Start();
        }

        /// <summary>
        /// 포커스 감시 타이머를 정지하고 해제합니다.
        /// </summary>
        private void StopFocusMonitor()
        {
            if (this._focusCheckTimer == null) return;

            this._focusCheckTimer.Stop();
            this._focusCheckTimer.Tick -= FocusCheckTimer_Tick;
            this._focusCheckTimer.Dispose();
            this._focusCheckTimer = null;
        }

        /// <summary>
        /// 타이머 틱마다 대상 프로세스 포커스 상태와 마우스 클릭 상태를 확인하고 오버레이 표시를 갱신합니다.
        /// </summary>
        private void FocusCheckTimer_Tick(object sender, EventArgs e)
        {
            this.SyncMousePressStateIfChanged();
            this.UpdateOverlayVisibilityByFocus(forceRefresh: false);
        }

        /// <summary>
        /// 현재 기능 활성 상태에 따라 커서 및 스킬 범위 오버레이의 표시 여부를 동기화합니다.
        /// </summary>
        private void UpdateOverlayVisibilityByFocus(bool forceRefresh)
        {
            bool isActive = this.IsFeatureActiveNow();
            if (!forceRefresh && isActive == this._isFeatureActiveCached)
            {
                return;
            }

            this._isFeatureActiveCached = isActive;

            if (!isActive)
            {
                this.HideCursorOverlay();
                this.HideSkillOverlay();
                return;
            }

            this.ShowCursorOverlay();
            this.ShowSkillOverlayIfEnabled();
            this.EnsureCursorOverlayAboveSkillOverlay();
        }

        /// <summary>
        /// 커서 오버레이(mCursorForm)가 스킬 범위 오버레이(mSkillForm)보다 항상 상단 Z-순서에 위치하도록 정렬합니다.
        /// </summary>
        private void EnsureCursorOverlayAboveSkillOverlay()
        {
            if (this.mCursorForm == null || this.mCursorForm.IsDisposed || !this.mCursorForm.Visible)
            {
                return;
            }

            if (!this.mCursorForm.IsHandleCreated)
            {
                IntPtr _ = this.mCursorForm.Handle;
            }

            if (this.mSkillForm != null && !this.mSkillForm.IsDisposed && this.mSkillForm.Visible)
            {
                if (!this.mSkillForm.IsHandleCreated)
                {
                    IntPtr _ = this.mSkillForm.Handle;
                }

                SetWindowPos(
                    this.mSkillForm.Handle,
                    HWND_TOPMOST,
                    0, 0, 0, 0,
                    SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
            }

            SetWindowPos(
                this.mCursorForm.Handle,
                HWND_TOPMOST,
                0, 0, 0, 0,
                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
        }
        #endregion

        #region [5. 마우스 후크 이벤트 분배 (Mouse Hook Dispatch)]
        /// <summary>
        /// 마우스 이동 이벤트 발생 시 커서(Form2)와 스킬 범위(Form3) 오버레이 좌표를 갱신합니다.
        /// </summary>
        private bool MouseHook_MouseMove(MouseEventType type, int x, int y)
        {
            try
            {
                this.SyncMousePressStateIfChanged();
                this.UpdateOverlayVisibilityByFocus(forceRefresh: false);
                if (!this._isFeatureActiveCached)
                {
                    return true;
                }

                this.UpdateCursorPosition(x, y);
                this.UpdateCustomSkillPosition(x, y);
            }
            catch (Exception)
            {
            }
            return true;
        }
        #endregion

        #region [6. 공통 설정 검증 및 INI 입출력 (Settings Apply & INI I/O)]
        /// <summary>
        /// UI에 입력된 각 모듈의 설정값을 검증하고 즉시 반영합니다.
        /// </summary>
        private void SettingApply_Save()
        {
            try
            {
                this.ApplyCursorSettingsFromUi();
                this.ApplySkillSettingsFromUi();
                this.ApplyConvenienceSettingsFromUi();
                this.ApplyStartupOptionsFromUi();
            }
            catch (Exception)
            {
            }
        }
        private bool TryLoadStartMinimizedSetting(string key, string value)
        {
            if (key == "StartMinimizedToTray" && bool.TryParse(value, out bool parsedStartMinimized))
            {
                this._startMinimizedToTray = parsedStartMinimized;
                return true;
            }
            return false;
        }

        /// <summary>
        /// INI 설정 파일에서 저장된 값을 읽어 필드에 반영하고 유효 범위를 보정합니다.
        /// </summary>
        private void LoadSettings()
        {
            try
            {
                if (File.Exists(this.configPath))
                {
                    string[] lines = File.ReadAllLines(this.configPath);
                    for (int i = 0; i < lines.Length; i++)
                    {
                        string line = lines[i].Trim();
                        if (string.IsNullOrEmpty(line)) continue;

                        int sepIndex = line.IndexOf('=');
                        if (sepIndex <= 0) continue;

                        string key = line.Substring(0, sepIndex).Trim();
                        string value = line.Substring(sepIndex + 1).Trim();

                        if (key == "OnlyWhenTalesWeaverRunning" && bool.TryParse(value, out bool parsedOnlyTw))
                        {
                            this._onlyWhenTalesWeaverRunning = parsedOnlyTw;
                        }
                        else if (!this.TryLoadCursorSetting(key, value)
                              && !this.TryLoadSkillSetting(key, value)
                              && !this.TryLoadConvenienceSetting(key, value))
                        {
                            this.TryLoadStartMinimizedSetting(key, value);
                        }
                    }
                }
            }
            catch (Exception)
            {
            }

            this.NormalizeCursorSettings();
            this.NormalizeSkillSettings();
            this.NormalizeConvenienceSettings();
        }

        /// <summary>
        /// 현재 설정값들을 INI 파일에 기록합니다.
        /// </summary>
        private void SaveSettings()
        {
            try
            {
                string cleanBase64 = string.IsNullOrEmpty(this.CursorBase64)
                    ? ""
                    : this.CursorBase64.Replace("\r", "").Replace("\n", "").Trim();

                string colorValue = this.Skill_CustomColor.HasValue
                    ? ColorTranslator.ToHtml(this.Skill_CustomColor.Value)
                    : "Default";

                string attackColorValue = ColorTranslator.ToHtml(this.Skill_AttackRangeColor);

                string contents = string.Format(
                    "OnlyWhenTalesWeaverRunning={0}\nSize={1}\nOpacity={2}\nCursor={3}\nSkillEnable_UserRange={4}\nSkillEnable_StraightRange={5}\nSkillEnable_CustomRange={6}\nSkill_RangeColor={7}\nSkill_AttackRangeColor={8}\nSkill_RangeExtension={9}\nSkill_RangeExtensionItem={10}\nSkill_Range={11}\nSkill_AttackRange={12}\nSkill_RangeOpacity={13}\nSpaceToEnter_Enable={14}\nSpaceToEnter_DurationMs={15}\nStartMinimizedToTray={16}",
                    new object[]
                    {
                this._onlyWhenTalesWeaverRunning,
                this.CursorSize,
                this.CursorOpacity,
                cleanBase64,
                this.SkillEnable_UserRange,
                this.SkillEnable_StraightRange,
                this.SkillEnable_CustomRange,
                colorValue,
                attackColorValue,
                this.Skill_RangeExtension,
                this.Skill_RangeExtensionItem,
                this.Skill_Range,
                this.Skill_AttackRange,
                this.Skill_RangeOpacity,
                this._spaceToEnterEnabled,
                this._spaceToEnterDurationMs,
                this._startMinimizedToTray
                    });
                File.WriteAllText(this.configPath, contents);
            }
            catch (Exception)
            {
            }
        }
        #endregion

        #region [7. 공통 UI 이벤트 핸들러 및 트레이 제어 (Common UI & Tray Handlers)]
        /// <summary>
        /// 상단 "TalesWeaver 실행 중에만 활성화" 버튼 클릭 시 제한 모드를 토글합니다.
        /// </summary>
        private void button_OnlyWhenTalesWeaverRunning_Click(object sender, EventArgs e)
        {
            try
            {
                this._onlyWhenTalesWeaverRunning = !this._onlyWhenTalesWeaverRunning;
                this.SyncOnlyWhenTalesWeaverRunningUi();

                if (!this._onlyWhenTalesWeaverRunning)
                {
                    this.ResetSpaceToEnterTimer();
                }

                this.UpdateOverlayVisibilityByFocus(forceRefresh: true);
            }
            catch (Exception ex)
            {
                MessageBox.Show("실행 제한 모드 변경 실패: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Hand);
            }
        }

        /// <summary>
        /// 트레이 또는 숨김 상태의 메인 폼을 화면에 복원하고 최상위로 활성화합니다.
        /// </summary>
        public void RestoreFromTray()
        {
            if (this.InvokeRequired)
            {
                this.Invoke(new Action(this.RestoreFromTray));
                return;
            }

            this.ShowInTaskbar = true;

            if (!this.Visible)
            {
                this.Show();
            }

            if (this.WindowState == FormWindowState.Minimized)
            {
                this.WindowState = FormWindowState.Normal;
            }

            this.Activate();
            this.BringToFront();
        }

        /// <summary>
        /// 중복 실행 시 기존 인스턴스를 활성화하기 위한 사용자 정의 윈도우 메시지를 처리합니다.
        /// </summary>
        protected override void WndProc(ref Message m)
        {
            if (m.Msg == Program.WM_SHOW_EXISTING_INSTANCE)
            {
                this.RestoreFromTray();
            }

            base.WndProc(ref m);
        }

        /// <summary>
        /// 폼 크기 변경 시 최소화 상태이면 메인 폼을 숨겨 트레이로 보냅니다.
        /// </summary>
        private void Form1_Resize(object sender, EventArgs e)
        {
            if (this.WindowState == FormWindowState.Minimized)
            {
                this.Hide();
            }
        }

        /// <summary>
        /// 폼 레이아웃 동기화 완료 후 메인 폼을 숨겨 트레이로 최소화합니다.
        /// </summary>
        private void MinimizeToTray()
        {
            this.EnsureFormLayoutSynced();

            if (this.WindowState != FormWindowState.Minimized)
            {
                this.WindowState = FormWindowState.Minimized;
            }
            this.Hide();
        }

        /// <summary>
        /// ESC 키 입력 시 메인 폼을 트레이로 숨깁니다.
        /// </summary>
        private void Form1_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Escape)
            {
                this.MinimizeToTray();
                e.Handled = true;
                e.SuppressKeyPress = true;
            }
        }

        /// <summary>
        /// 트레이 메뉴 [열기] 클릭 시 메인 폼을 복원합니다.
        /// </summary>
        private void TrayMenu_Open_Click(object sender, EventArgs e)
        {
            this.RestoreFromTray();
        }

        /// <summary>
        /// 트레이 메뉴 [종료] 클릭 시 애플리케이션을 종료합니다.
        /// </summary>
        private void TrayMenu_Exit_Click(object sender, EventArgs e)
        {
            if (this.notifyIcon1 != null)
            {
                this.notifyIcon1.Visible = false;
            }
            Application.Exit();
        }

        /// <summary>
        /// 트레이 아이콘 더블클릭 시 메인 폼을 복원합니다.
        /// </summary>
        private void NotifyIcon_DoubleClick(object sender, EventArgs e)
        {
            this.RestoreFromTray();
        }

        /// <summary>
        /// 텍스트박스에서 Enter 키 입력 시 설정을 즉시 적용합니다.
        /// </summary>
        private void textBox_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Return)
            {
                this.SettingApply_Save();
            }
        }

        /// <summary>
        /// [설정값 저장] 버튼 클릭 시 설정을 적용하고 INI 파일에 저장합니다.
        /// </summary>
        private void button_Apply_Click(object sender, EventArgs e)
        {
            try
            {
                this.SettingApply_Save();
                MessageBox.Show("설정값이 저장되었습니다.", "Success", MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
                this.SaveSettings();
            }
            catch (Exception)
            {
            }
        }

        /// <summary>
        /// 폼 로드 시 레지스트리 및 INI 상태를 읽어 하단 시작 옵션 체크박스 UI를 동기화합니다.
        /// </summary>
        /// <summary>
        /// 폼 로드 시 레지스트리 및 INI 상태를 읽어 하단 시작 옵션 체크박스 UI를 동기화합니다.
        /// </summary>
        private void InitStartupOptionsUiOnLoad()
        {
            if (this.checkBox_RunAtStartup != null)
            {
                this.checkBox_RunAtStartup.Checked = this.IsRegisteredInStartup();
            }
            if (this.checkBox_StartMinimized != null)
            {
                this.checkBox_StartMinimized.Checked = this._startMinimizedToTray;
            }
        }

        /// <summary>
        /// '설정값 저장' 시점에 체크박스 상태를 기준으로 시작 프로그램 레지스트리 및 시작 시 트레이 최소화 설정을 적용합니다.
        /// </summary>
        private void ApplyStartupOptionsFromUi()
        {
            if (this.checkBox_RunAtStartup != null)
            {
                bool desiredRunAtStartup = this.checkBox_RunAtStartup.Checked;
                try
                {
                    this.SetRunAtStartup(desiredRunAtStartup);
                }
                catch (Exception ex)
                {
                    MessageBox.Show("시작 프로그램 등록 설정에 실패했습니다: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Hand);
                    this.checkBox_RunAtStartup.Checked = this.IsRegisteredInStartup();
                }
            }

            if (this.checkBox_StartMinimized != null)
            {
                this._startMinimizedToTray = this.checkBox_StartMinimized.Checked;
            }
        }

        /// <summary>
        /// 현재 실행 파일이 Windows 시작 프로그램 레지스트리에 등록되어 있는지 확인합니다.
        /// </summary>
        private bool IsRegisteredInStartup()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(STARTUP_REGISTRY_KEY_PATH, false))
                {
                    if (key == null) return false;
                    object value = key.GetValue(STARTUP_APP_NAME);
                    if (value == null) return false;

                    string regPath = value.ToString().Trim('"');
                    return string.Equals(regPath, Application.ExecutablePath, StringComparison.OrdinalIgnoreCase);
                }
            }
            catch
            {
                return false;
            }
        }

        /// <summary>
        /// Windows 시작 프로그램 레지스트리에 현재 실행 파일을 등록하거나 해제합니다.
        /// </summary>
        private void SetRunAtStartup(bool enable)
        {
            using (RegistryKey key = Registry.CurrentUser.OpenSubKey(STARTUP_REGISTRY_KEY_PATH, true))
            {
                if (key == null)
                {
                    throw new InvalidOperationException("시작 프로그램 레지스트리 키를 열 수 없습니다.");
                }

                if (enable)
                {
                    key.SetValue(STARTUP_APP_NAME, $"\"{Application.ExecutablePath}\"");
                }
                else if (key.GetValue(STARTUP_APP_NAME) != null)
                {
                    key.DeleteValue(STARTUP_APP_NAME, false);
                }
            }
        }

        /// <summary>
        /// '시작 프로그램 등록' 체크박스 상태 변경 이벤트(실제 반영은 '설정값 저장' 시 수행).
        /// </summary>
        private void checkBox_RunAtStartup_CheckedChanged(object sender, EventArgs e)
        {
        }

        /// <summary>
        /// '시작 시 트레이 최소화' 체크박스 상태 변경 이벤트(실제 반영 및 INI 저장은 '설정값 저장' 시 수행).
        /// </summary>
        private void checkBox_StartMinimized_CheckedChanged(object sender, EventArgs e)
        {
        }
        #endregion
    }
}